    console.log('✗ Floating point failed:', e.message);
}

// Test 5: Large numbers
try {
    assert.strictEqual(add(1000, 2000), 3000);
    console.log('✓ Large numbers (1000 + 2000 = 3000)');
} catch (e) {
    console.log('✗ Large numbers failed:', e.message);
}

